package operatoraccess

import (
	"slices"
	"sort"
	"strings"
)

type Kind uint8

const (
	KindModule Kind = iota + 1 // module + level (+ any_of, flags)
	KindSuperOnly
	KindAnyAdmin
)

type (
	TargetRule string // Catalog §2.1 ids, for example "user_path_id"
	FieldRule  string // Catalog §2.2 ids
	Redaction  string // Catalog §2.3 ids
)

type Entry struct {
	Kind   Kind
	Module Module
	Level  Level
	AnyOf  []Module
	Flags  []Flag
	Target TargetRule
	Fields FieldRule
	Redact []Redaction
	WS     bool
}

const (
	AdminPrefix       = "/api/v1/admin"
	MeAccessKey       = "GET /me/access"
	DownloadTicketKey = "GET /usage/exports/:id/download"
)

// Key builds the catalog key: method + " " + FullPath with AdminPrefix stripped.
// A FullPath outside AdminPrefix (the pages group) is kept absolute.
func Key(method, fullPath string) string {
	if fullPath == AdminPrefix || strings.HasPrefix(fullPath, AdminPrefix+"/") {
		fullPath = strings.TrimPrefix(fullPath, AdminPrefix)
	}
	return method + " " + fullPath
}
func Lookup(key string) (Entry, bool) {
	e, ok := catalog[key]
	e.AnyOf = slices.Clone(e.AnyOf)
	e.Flags = slices.Clone(e.Flags)
	e.Redact = slices.Clone(e.Redact)
	return e, ok
}
func Keys() []string {
	keys := make([]string, 0, len(catalog))
	for k := range catalog {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

